 9→} from 'typeorm';
10→import { User } from '../../auth/entities/user.entity';
11→
12→@Entity('share_invites')
13→export class ShareInvite {
14→  @PrimaryGeneratedColumn('uuid')
15→  id!: string;
16→
17→  @Column({ type: 'varchar', length: 44, name: 'token', unique: true })
18→  token!: string;
19→
20→  @Index()
21→  @Column({ type: 'uuid', name: 'sharer_id' })
22→  sharerId!: string;
23→
24→  @ManyToOne(() => User, { onDelete: 'CASCADE' })
25→  @JoinColumn({ name: 'sharer_id' })
26→  sharer!: User;
27→
28→  @Column({ type: 'varchar', length: 10, name: 'item_type' })
29→  itemType!: 'folder' | 'file';
30→
31→  @Column({ type: 'varchar', length: 255, name: 'ipns_name' })
32→  ipnsName!: string;
33→
34→  @Column({ type: 'varchar', length: 255, name: 'item_name' })
35→  itemName!: string;
36→
37→  /**
38→   * The item key wrapped with the EPHEMERAL public key (not recipient's key).
39→   * Server never sees the ephemeral private key -- it lives only in the URL fragment.
40→   */
41→  @Column({ type: 'bytea', name: 'encrypted_key' })
42→  encryptedKey!: Buffer;
43→
44→  /**
45→   * Child keys (subfolder/file keys) wrapped with ephemeral public key.
46→   * Stored as JSONB for simplicity -- invites are short-lived (7 days).
47→   */
48→  @Column({ type: 'jsonb', name: 'encrypted_child_keys', nullable: true })
49→  encryptedChildKeys!: Array<{
50→    keyType: 'file' | 'folder';
51→    itemId: string;
52→    encryptedKey: string; // hex
53→  }> | null;
54→
55→  @Column({ type: 'varchar', length: 20, default: 'active' })
56→  status!: 'active' | 'claimed' | 'revoked';
57→
58→  @Column({ type: 'integer', name: 'max_claims', default: 1 })
59→  maxClaims!: number;
60→
61→  @Column({ type: 'integer', name: 'claim_count', default: 0 })
62→  claimCount!: number;
63→
64→  @Column({ type: 'uuid', name: 'claimed_by', nullable: true })
65→  claimedBy!: string | null;
66→
67→  @Index()
68→  @Column({ type: 'timestamp', name: 'expires_at' })
69→  expiresAt!: Date;
70→
71→  @CreateDateColumn({ name: 'created_at' })
72→  createdAt!: Date;
73→}
