      const result = await controller.getShareKeys(mockReq, shareId);

      expect(result).toEqual([]);
    });

    it('should map multiple keys with different types', async () => {
      const mockKeys: ShareKey[] = [
        {
          id: 'k1',
          shareId,
          keyType: 'file',
